const VennExplainer: React.FC<VennExplainerProps> = ({
  backgroundColor = "#F8FAFC",
  transparentBackground = false,
  durationInSeconds = 15,
  title = "System Architecture",
  subtitle = "Data flow from end-users to the central platform",
  inputNodes = [
    { label: "Acute\nPatients", icon: "bed" },
    { label: "Chronic\nPatients", icon: "heart" },
    { label: "Pregnant\nWomen", icon: "pregnant" }
  ],
  pipelineNodes = [
    { label: "Medical\nSensors", icon: "sensor" },
    { label: "Mobile\nGateway", icon: "mobile" },
    { label: "Cloud\nServer", icon: "cloud" },
    { label: "Web\nPortal", icon: "desktop" }
  ],
  outputNodes = [
    { label: "Healthcare\nProfessionals", icon: "doctors" },
    { label: "Manager &\nAdministrator", icon: "manager" },
    { label: "Ambulance &\nEmergency", icon: "ambulance" }
  ],
  primaryColor = "#0284C7",
  accentColor = "#93C5FD",
  textColor = "#0F172A",
}) => {
  useFontLoader(["Playfair Display", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // -- Data Flow Layout Math --
  const columns = [inputNodes, ...pipelineNodes.map((n) => [n]), outputNodes];

  const nodePositions = columns.map((col, i) => {
    // Spread columns horizontally across 70% of the screen
    const cx = width * 0.15 + i * ((width * 0.7) / Math.max(1, columns.length - 1));
    
    return col.map((node, j) => {
      const N = col.length;
      let cy = height * 0.55; // Base vertical center, slightly lower to accommodate title
      
      if (N > 1) {
        const totalGap = height * 0.6; // Vertical spread area
        const startY = height * 0.55 - totalGap / 2;
        cy = startY + j * (totalGap / (N - 1));
      }
      return { cx, cy, label: node.label, icon: node.icon };
    });
  });

  const edges: { x1: number; y1: number; x2: number; y2: number; colIndex: number }[] = [];
  for (let i = 0; i < nodePositions.length - 1; i++) {
    const currentCol = nodePositions[i];
    const nextCol = nodePositions[i + 1];
    for (const n1 of currentCol) {
      for (const n2 of nextCol) {
        edges.push({
          x1: n1.cx,
          y1: n1.cy,
          x2: n2.cx,
          y2: n2.cy,
          colIndex: i,
        });
      }
    }
  }

  const stagger = 15; // Frames between each column appearing

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      
      {/* Title & Subtitle */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          width: width,
          textAlign: "center",
          opacity: interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" }),
          transform: `translateY(${interpolate(frame, [0, 20], [-20, 0], { extrapolateRight: "clamp" })}px)`,
          transition: "none",
        }}
      >
        <h1
          style={{
            fontFamily: "Playfair Display",
            fontSize: 48,
            fontWeight: 700,
            color: textColor,
            margin: 0,
            transition: "none",
          }}
        >
          {title}
        </h1>
        <p
          style={{
            fontFamily: "Inter",
            fontSize: 24,
            color: textColor,
            opacity: 0.7,
            margin: "10px 0 0 0",
            transition: "none",
          }}
        >
          {subtitle}
        </p>
      </div>

      {/* Connection Lines & Data Particles */}
      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          overflow: "visible",
          transition: "none",
        }}
      >
        {edges.map((edge, idx) => {
          const drawStart = edge.colIndex * stagger + 10;
          
          const drawProgress = spring({
            frame: frame - drawStart,
            fps,
            config: { damping: 20 },
          });

          const dx = edge.x2 - edge.x1;
          const dy = edge.y2 - edge.y1;
          const angle = Math.atan2(dy, dx);
          
          // Offset start and end points to sit at the edge of the 80px circle (40 radius + 5 padding)
          const boxOffset = 45; 

          const startX = edge.x1 + Math.cos(angle) * boxOffset;
          const startY = edge.y1 + Math.sin(angle) * boxOffset;

          const endTargetX = edge.x2 - Math.cos(angle) * boxOffset;
          const endTargetY = edge.y2 - Math.sin(angle) * boxOffset;

          const dist = Math.sqrt(Math.pow(endTargetX - startX, 2) + Math.pow(endTargetY - startY, 2));
          if (dist <= 0) return null;

          const currentX = interpolate(drawProgress, [0, 1], [startX, endTargetX]);
          const currentY = interpolate(drawProgress, [0, 1], [startY, endTargetY]);

          const angleDeg = (angle * 180) / Math.PI;

          // Looping data particle
          const particleDuration = 60;
          const pProgress = ((frame - (drawStart + 20)) % particleDuration) / particleDuration;
          const px = interpolate(pProgress, [0, 1], [startX, endTargetX]);
          const py = interpolate(pProgress, [0, 1], [startY, endTargetY]);
          const pOpacity = interpolate(pProgress, [0, 0.1, 0.9, 1], [0, 1, 1, 0], {
            extrapolateRight: "clamp",
            extrapolateLeft: "clamp",
          });

          return (
            <g key={`edge-${idx}`}>
              <line
                x1={startX}
                y1={startY}
                x2={currentX}
                y2={currentY}
                stroke={accentColor}
                strokeWidth={3}
                opacity={0.6}
                style={{ transition: "none" }}
              />
              
              {/* Arrowhead */}
              {drawProgress > 0.95 && (
                <polygon
                  points="0,-5 10,0 0,5"
                  fill={accentColor}
                  transform={`translate(${endTargetX}, ${endTargetY}) rotate(${angleDeg})`}
                  style={{ transition: "none" }}
                />
              )}

              {/* Moving Data Particle */}
              {frame >= drawStart + 20 && (
                <circle
                  cx={px}
                  cy={py}
                  r={5}
                  fill={primaryColor}
                  opacity={pOpacity}
                  style={{ transition: "none", filter: `drop-shadow(0 0 4px ${primaryColor})` }}
                />
              )}
            </g>
          );
        })}
      </svg>

      {/* Nodes */}
      {nodePositions.map((col, i) => {
        return col.map((node, j) => {
          const appearStart = i * stagger;
          const scale = spring({
            frame: frame - appearStart,
            fps,
            config: { damping: 15, mass: 0.8 },
          });
          const opacity = interpolate(frame - appearStart, [0, 10], [0, 1], {
            extrapolateRight: "clamp",
            extrapolateLeft: "clamp"
          });

          const isOutputNode = i === columns.length - 1;
          const iconColor = isOutputNode ? textColor : primaryColor;

          return (
            <div
              key={`node-${i}-${j}`}
              style={{
                position: "absolute",
                left: node.cx - 40,
                top: node.cy - 40,
                width: 80,
                height: 80,
                opacity,
                transform: `scale(${scale})`,
                transition: "none",
                zIndex: 10,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              <NodeIcon type={node.icon} color={iconColor} size={64} bg={backgroundColor} />

              {/* Node Label */}
              <div
                style={{
                  position: "absolute",
                  top: 90,
                  left: -60, // Centers a 200px wide box under an 80px node
                  width: 200,
                  textAlign: "center",
                  color: textColor,
                  fontFamily: "Inter",
                  fontSize: 18,
                  fontWeight: 600,
                  whiteSpace: "pre-wrap",
                  lineHeight: 1.3,
                  transition: "none",
                }}
              >
                {node.label}
              </div>
            </div>
          );
        });
      })}
      
    </AbsoluteFill>
  );
};

export default VennExplainer;